enum Numeric { Zero, Five = 5, Negative = -2, Fraction = 1.5 }
enum Aliased { First = 3, Second = 3 }
enum Strings { First = 'one', Second = 'two' }
enum Mixed { Zero = 0, Word = 'word', Two = 2 }
const cases = [
  [Numeric, [0, 5, -2, 1.5], ['Zero', 'Five', 'Negative', 'Fraction', '0', '5', 1, null]],
  [Aliased, [3, 3], ['First', 'Second', '3', 0]],
  [Strings, ['one', 'two'], ['First', 'Second', 0]],
  [Mixed, [0, 'word', 2], ['Zero', 'Word', 'Two', '0', 1]],
  [['a', 'b'], ['a', 'b'], ['c', 0]],
  [{ First: 'one', Alias: 'one' }, ['one', 'one'], ['First', 'Alias']],
  [{}, [], ['anything', 0]],
] as const;
for (const api of [classic, mini]) {
  for (const make of [api.enum, api.nativeEnum]) {
    for (const [entries, accepted, rejected] of cases) {
      if (make === api.nativeEnum && Array.isArray(entries)) continue;
      const schema = make(entries as any);
      assert.deepEqual(schema.options, accepted);
      for (const value of accepted) assert.equal(schema.parse(value), value);
      for (const value of rejected) assert.equal(schema.safeParse(value).success, false);
    }
  }
}
