import assert from 'node:assert/strict'
import { build } from 'esbuild'

const bundled = await build({
  stdin: {
    contents: \"export { Hono } from './src/index.ts'; export { prettyJSON } from './src/middleware/pretty-json/index.ts'\",
    resolveDir: process.cwd(),
    loader: 'ts',
  },
  bundle: true,
  platform: 'node',
  format: 'esm',
  write: false,
})
const { Hono, prettyJSON } = await import('data:text/javascript;base64,' + Buffer.from(bundled.outputFiles[0].text).toString('base64'))
let checks = 0
async function invoke(response, options, query = '?pretty') {
  const params = new URLSearchParams(query)
  const context = { res: response, req: { query: (name) => params.get(name) ?? undefined } }
  await prettyJSON(options)(context, async () => {})
  return context.res
}
for (const body of ['{invalid', '', '   ', '{\"missing\":', 'undefined']) {
  const original = new Response(body, { status: 422, statusText: 'Unprocessable Content', headers: { 'Content-Type': 'application/json', 'Content-Length': String(body.length), 'X-Preserved': 'yes' } })
  const headers = [...original.headers]
  const result = await invoke(original)
  assert.equal(result, original)
  assert.equal(result.bodyUsed, false)
  assert.equal(result.status, 422)
  assert.equal(result.statusText, 'Unprocessable Content')
  assert.deepEqual([...result.headers], headers)
  assert.equal(await result.text(), body)
  checks++
}
for (const status of [200, 204, 304]) {
  const original = new Response(null, { status, headers: { 'Content-Type': 'application/json', 'Content-Length': '0', 'X-Preserved': 'yes' } })
  const headers = [...original.headers]
  const result = await invoke(original)
  assert.equal(result, original)
  assert.equal(result.status, status)
  assert.deepEqual([...result.headers], headers)
  assert.equal(result.body, null)
  checks++
}
const consumed = new Response('{\"ok\":true}', { headers: { 'Content-Type': 'application/json', 'Content-Length': '11' } })
await consumed.text()
assert.equal(await invoke(consumed), consumed)
assert.equal(consumed.headers.get('Content-Length'), '11')
checks++
const locked = new Response('{\"ok\":true}', { headers: { 'Content-Type': 'application/json' } })
const reader = locked.body.getReader()
assert.equal(await invoke(locked), locked)
reader.releaseLock()
assert.equal(await locked.text(), '{\"ok\":true}')
checks++
for (const [contentType, body, options, query] of [
  ['application/json', '{\"ok\":true}', undefined, '?pretty'],
  ['Application/Problem+JSON; charset=utf-8', '{\"items\":[1,2]}', { space: 4 }, '?pretty'],
  ['application/json', '[1,{\"ok\":true}]', { force: true }, ''],
  ['application/json', 'null', { query: 'format', space: 0 }, '?format'],
  ['application/json', 'false', undefined, '?pretty'],
]) {
  const app = new Hono()
  app.use(prettyJSON(options))
  app.get('/', () => new Response(body, { status: 201, statusText: 'Custom Created', headers: { 'Content-Type': contentType, 'Content-Length': String(body.length), 'X-Preserved': 'yes', 'Set-Cookie': 'session=value' } }))
  const result = await app.request('/' + query)
  assert.equal(result.status, 201)
  assert.equal(result.statusText, 'Custom Created')
  assert.equal(result.headers.get('Content-Length'), null)
  assert.equal(result.headers.get('Content-Type'), contentType)
  assert.equal(result.headers.get('X-Preserved'), 'yes')
  assert.equal(result.headers.get('Set-Cookie'), 'session=value')
  assert.equal(await result.text(), JSON.stringify(JSON.parse(body), null, options?.space ?? 2))
  checks++
}
for (const [contentType, query] of [['application/json', ''], ['text/plain', '?pretty'], ['application/jsonp', '?pretty']]) {
  const original = new Response('{\"ok\":true}', { headers: { 'Content-Type': contentType, 'Content-Length': '11' } })
  assert.equal(await invoke(original, undefined, query), original)
  assert.equal(original.bodyUsed, false)
  assert.equal(original.headers.get('Content-Length'), '11')
  checks++
}
console.log("'`${checks} focused prettyJSON checks passed`)
NODE'

